import {previewSplash,themes,themeForDate,themeSchedule} from './splash.js';
import {semanticUI} from './semantic-ui.js';
import {wordHint,score,dayKey,dailyAnswer,outcome,statistics,newState,validateState} from './core.js';
import {puzzleUI} from './puzzle-ui.js';
import {answers,words} from './words.js';
const APP_VERSION='1.4.0';
const allowed=new Set([...words,...answers]), KEY='wordgarden-v1', $=s=>document.querySelector(s), main=$('#main');
let state=newState(), view='today', draft='', today=dayKey(), toastTimer, offlineReady=false, storageOK=true, recoveryRaw=null;
try {const raw=localStorage.getItem(KEY);if(raw)state=validateState(JSON.parse(raw),answers,allowed);}catch(e){storageOK=false;try{recoveryRaw=localStorage.getItem(KEY);}catch{}setTimeout(()=>toast('Saved data could not be loaded. Export it in Settings before resetting.'),400);}
function save(){if(recoveryRaw!==null){storageOK=false;connection();return;}try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch{storageOK=false;toast('Unable to save on this device. Export a backup in Settings.');}connection();}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',3600);}
const puzzles=puzzleUI({$,main,toast,save,confirmAction,showDialog,state:()=>state,today:()=>today,view:()=>view});
const semantic=semanticUI({$,main,toast,save,confirmAction,state:()=>state,today:()=>today});
function game(){if(view==='today'){if(!state.daily[today]){state.daily[today]={id:today,date:today,mode:'daily',answer:dailyAnswer(today,answers),guesses:[]};save();}return state.daily[today];}if(view==='practice'){let g=state.practice.find(g=>g.id===state.activePractice);if(!g){createPractice();g=state.practice.at(-1);}return g;}}
function createPractice(){let pool=answers.filter(w=>w!==dailyAnswer(today,answers)&&!state.practice.slice(-20).some(g=>g.answer===w));if(!pool.length)pool=answers;const n=new Uint32Array(1);crypto.getRandomValues(n);const g={id:crypto.randomUUID(),date:today,mode:'practice',answer:pool[n[0]%pool.length],guesses:[]};state.practice.push(g);state.activePractice=g.id;draft='';save();}
function legend(){return '<div class="legend"><div><span class="sample correct">✓</span>Right letter, right place</div><div><span class="sample present">↔</span>Right letter, different place</div><div><span class="sample absent">×</span>Not in the word</div></div>';}
function applySettings(){document.body.classList.toggle('contrast',state.settings.contrast);document.body.classList.toggle('reduce-motion',state.settings.motion);}
function render(reveal=false){applySettings();document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('selected',b.dataset.view===view);if(b.dataset.view===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});if(view==='today'||view==='practice')renderGame(reveal);else if(view==='sudoku'||view==='ladder')puzzles.render(view);else if(view==='semantic')semantic.render();else if(view==='progress')renderProgress();else renderSettings();}
function renderGame(reveal){const g=game();draft=g.draft||'';const status=outcome(g), stats=statistics(state.daily,today), daily=view==='today';
const dateLabel=new Date(today+'T12:00:00Z').toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric',timeZone:'UTC'});
const rows=Array.from({length:6},(_,i)=>{const guess=g.guesses[i]|| (i===g.guesses.length?draft:''),marks=g.guesses[i]?score(guess,g.answer):[];return `<div class="board-row ${reveal&&i===g.guesses.length-1?'reveal':''}" role="row">${Array.from({length:5},(_,j)=>`<div role="gridcell" class="tile ${marks[j]|| (guess[j]?'filled':'')}" style="--i:${j}" aria-label="${guess[j]?guess[j].toUpperCase()+', '+(marks[j]||'not submitted'):'empty'}">${(guess[j]||'').toUpperCase()}${state.settings.contrast&&marks[j]?`<i aria-hidden="true">${{correct:'✓',present:'↔',absent:'×'}[marks[j]]}</i>`:''}</div>`).join('')}</div>`;}).join('');
const ranks={absent:1,present:2,correct:3}, keyMarks={};for(const w of g.guesses)score(w,g.answer).forEach((m,i)=>{if((ranks[keyMarks[w[i]]]||0)<ranks[m])keyMarks[w[i]]=m;});
const keyboard=['qwertyuiop','asdfghjkl','↵zxcvbnm⌫'].map(row=>`<div class="key-row">${[...row].map(c=>`<button class="key ${c==='↵'||c==='⌫'?'wide':''} ${keyMarks[c]||''}" data-key="${c}" aria-label="${c==='↵'?'Submit guess':c==='⌫'?'Delete letter':c.toUpperCase()+(keyMarks[c]?', '+keyMarks[c]:'')}" ${status!=='playing'?'disabled':''}>${c==='↵'?'ENTER':c==='⌫'?'⌫':c.toUpperCase()}</button>`).join('')}</div>`).join('');
main.innerHTML=`<section class="play-layout"><div class="intro"><div class="eyebrow">${daily?'Your daily pause':'A little room to grow'}</div><h1>${daily?'A little wordplay,<br>every day.':'Practice makes<br>possibilities.'}</h1><p>One hidden word. Six chances.<br>Follow the clues and see what blooms.</p><div class="date-chip"><span class="dot"></span>${daily?dateLabel+' · ET':'Unlimited puzzles · No streak pressure'}</div>${legend()}<div class="mini-stats"><div><b>${stats.streak}</b><span>day streak</span></div><div><b>${stats.played}</b><span>daily puzzles</span></div><div><b>${stats.winRate}%</b><span>win rate</span></div></div></div><div class="game"><div class="game-top"><span>${daily?'Daily word':'Practice word'}</span><span>${Math.min(g.guesses.length+1,6)} / 6 attempts</span></div><div class="board" role="grid" aria-label="Six guesses of five letters">${rows}</div><div class="message" role="status" aria-live="polite">${status==='playing'?(g.guesses.length?'Keep following the clues.':'Start with any five-letter word.'):(status==='won'?'Beautifully done.':'A new word is a new beginning.')}</div><div class="keyboard" aria-label="Letter keyboard">${keyboard}</div><div class="actions puzzle-help"><button class="secondary" data-action="hint" ${status!=='playing'?'disabled':''}>Hint</button><button class="secondary" data-action="answer">Show answer</button></div>${g.hintPositions?.length?`<p class="note">Letter hints: <strong>${[...g.answer].map((c,i)=>g.hintPositions.includes(i)?c.toUpperCase():'_').join(' ')}</strong> · ${g.hintPositions.length} used</p>`:''}${status!=='playing'?`<div class="result"><h2>${status==='revealed'?'Answer revealed':status==='won'?'You found it.':'The word was…'}</h2><p><strong>${g.answer.toUpperCase()}</strong> · ${status==='revealed'?'Not counted as a win':status==='won'?g.guesses.length+' of 6 guesses':'Try again with a fresh puzzle'}</p><div class="actions"><button class="primary" data-action="share">Share result ↗</button><button class="secondary" data-action="${daily?'practice':'new'}">${daily?'Keep playing':'Next puzzle'} →</button></div>${daily?'<p class="note">Next daily puzzle at midnight Eastern.</p>':''}</div>`:(!daily?'<div class="actions"><button class="text-button" data-action="new">Start another puzzle</button></div>':'')}</div></section>`;
main.querySelectorAll('[data-key]').forEach(b=>b.onclick=()=>input(b.dataset.key));main.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));}
function input(key){if(!['today','practice'].includes(view)||$('#dialog').open||$('#splash-screen')?.open)return; if(checkDay())return;const g=game();if(outcome(g)!=='playing')return;
if(key==='Backspace'||key==='⌫')draft=draft.slice(0,-1);else if(key==='Enter'||key==='↵'){if(draft.length!==5)return toast('Enter a five-letter word.');if(!allowed.has(draft))return toast('That word is not in this dictionary.');if(g.guesses.includes(draft))return toast('You already tried that word.');g.guesses.push(draft);g.draft='';const spoken=score(draft,g.answer).map((s,i)=>draft[i].toUpperCase()+' '+s).join(', ');draft='';save();render(true);$('.message').textContent=outcome(g)==='playing'?spoken:outcome(g)==='won'?'Solved in '+g.guesses.length+' guesses.':'The answer was '+g.answer.toUpperCase()+'.';return;}else if(/^[a-z]$/i.test(key)&&draft.length<5)draft+=key.toLowerCase();else return;g.draft=draft;save();render();}
function switchView(v){setMenu(false,true);if(!['today','practice','sudoku','ladder','semantic','progress','settings'].includes(v))v='today';view=v;draft='';history.replaceState(null,'','#'+v);render();}
function showDialog(title,html){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=html;$('#dialog').showModal();}
function confirmAction(title,description,fn){showDialog(title,`<p>${description}</p><div class="actions"><button id="cancel" class="secondary">Cancel</button><button id="confirm" class="primary">Continue</button></div>`);$('#cancel').onclick=()=>$('#dialog').close();$('#confirm').onclick=()=>{$('#dialog').close();fn();};}
function action(a){if(a==='hint'){if(checkDay())return;const g=game(),hint=wordHint(g);if(!hint)return toast('All letter positions are already known.');save();render();showDialog('A letter hint',`<p>Letter ${hint.index+1} is <strong>${hint.letter.toUpperCase()}</strong>.</p><p>This hint does not use a guess.</p>`);}else if(a==='answer'){if(checkDay())return;const g=game();if(outcome(g)!=='playing'){showDialog('The answer',`<p><strong>${g.answer.toUpperCase()}</strong></p>`);return;}confirmAction('Show the answer?','This ends this puzzle and will not count as a win.',()=>{if(outcome(g)!=='playing')return;g.revealed=true;g.draft='';draft='';save();render();});}else if(a==='practice')switchView('practice');else if(a==='new'){const run=()=>{createPractice();render();};if(outcome(game())==='playing'&&game().guesses.length)confirmAction('Start a fresh puzzle?','Your current practice puzzle will be left unfinished. Daily progress is unaffected.',run);else run();}else if(a==='share')share();}
async function share(){const g=game();const squares=state.settings.contrast?{correct:'🟦',present:'🟧',absent:'⬜'}:{correct:'🟩',present:'🟨',absent:'⬜'};const text=`Wordgarden ${g.mode==='daily'?g.date:'Practice'} ${outcome(g)==='won'?g.guesses.length:'X'}/6${g.revealed?' · Answer revealed':''}${g.hintPositions?.length?' · '+g.hintPositions.length+' hints':''}\n\n${g.guesses.map(w=>score(w,g.answer).map(m=>squares[m]).join('')).join('\n')}\n\n${location.href.split('#')[0]}`;
try{if(navigator.share){await navigator.share({title:'Wordgarden',text});return;}await navigator.clipboard.writeText(text);toast('Result copied. No answer spoilers.');}catch(e){if(e.name==='AbortError')return;showDialog('Share your result','<p>Copy the result below:</p><textarea id="share-text" readonly></textarea>');$('#share-text').value=text;$('#share-text').select();}}
function renderProgress(){const s=statistics(state.daily,today), p=statistics(state.practice,today), max=Math.max(...s.dist,1), historyGames=Object.values(state.daily).filter(g=>outcome(g)!=='playing').sort((a,b)=>b.date.localeCompare(a.date)).slice(0,10);main.innerHTML=`<section class="section"><div class="section-heading"><h1>Your growing collection.</h1><p>A record of the little wins.</p></div><div class="stats-grid">${[[s.played,'Daily puzzles played'],[s.winRate+'%','Daily win rate'],[s.streak,'Current day streak'],[s.best,'Best day streak']].map(([n,t])=>`<div class="stat"><strong>${n}</strong><span>${t}</span></div>`).join('')}</div><div class="progress-columns"><div class="panel"><h2>Guess distribution</h2><p class="note">Daily wins, by number of guesses</p><div class="distribution">${s.dist.map((n,i)=>`<div class="bar-row"><span>${i+1}</span><div class="bar" style="width:${Math.max(8,n/max*88)}%" aria-label="${i+1} guesses: ${n} wins">${n}</div></div>`).join('')}</div></div><div class="panel"><h2>Recent days</h2>${historyGames.length?historyGames.map(g=>`<div class="history-row"><span>${g.date}</span><strong>${outcome(g)==='won'?g.guesses.length+'/6 ✓':g.revealed?'Revealed':'X/6'}</strong></div>`).join(''):'<p class="empty">Your first completed daily puzzle will appear here.</p>'}</div></div><p class="note">Practice: ${p.played} completed · ${p.winRate}% won. Practice never changes your daily streak.</p><div class="extra-stats"><div class="panel"><h2>Semantic Guessing</h2><strong>${state.extras.semantic.history.length}</strong><p class="note">puzzles completed</p></div><div class="panel"><h2>Sudoku</h2><strong>${state.extras.sudoku.history.length}</strong><p class="note">puzzles completed</p></div><div class="panel"><h2>Word Ladder</h2><strong>${state.extras.ladder.history.length}</strong><p class="note">ladders completed</p></div></div></section>`;}
function download(content,name,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);}
function renderSettings(){main.innerHTML=`<section class="section"><div class="section-heading"><h1>Make yourself at home.</h1><p>Your game, your pace.</p></div><div class="settings-grid"><div class="panel splash-settings"><h2>A seasonal welcome</h2><p>Jigsaw pieces come together for three seconds when you open the app. The design changes automatically, even offline. Play now skips straight to your puzzle.</p><p><strong>Current design: ${themes[themeForDate()].label}</strong></p><label for="splash-preview-theme">Preview a design</label><div class="splash-preview-controls"><select id="splash-preview-theme">${Object.entries(themes).map(([id,t])=>`<option value="${id}" ${id===themeForDate()?'selected':''}>${t.label}</option>`).join('')}</select><button class="secondary" id="splash-preview">Preview</button></div><details><summary>Automatic theme calendar</summary><ul class="splash-schedule">${themeSchedule.map(t=>`<li>${t.label}: ${t.window}</li>`).join('')}<li>Generic: all other dates</li></ul><p>Dates use Eastern time. Holiday designs take priority over seasonal designs; summer resumes after July 4th. Previews do not change the automatic calendar.</p></details><p class="note">Reduce motion shows a still design for the same three seconds.</p></div><div class="panel"><h2>Comfort & clarity</h2><div class="setting-row"><label for="contrast">Accessible colors<small>Blue and orange tiles, with clue symbols.</small></label><input id="contrast" type="checkbox" ${state.settings.contrast?'checked':''}></div><div class="setting-row"><label for="motion">Reduce motion<small>Turn off tile reveal animations.</small></label><input id="motion" type="checkbox" ${state.settings.motion?'checked':''}></div><p>Correct ✓ · Different position ↔ · Absent ×</p></div><div class="panel"><h2>On your home screen</h2><ol class="install-steps"><li>Open this app in Safari on your iPhone.</li><li>Tap Share, then <strong>Add to Home Screen</strong>.</li><li>Tap Add. Look for the gameboard icon.</li></ol><p>Open once online and wait for “Ready offline” below. Then play downloaded puzzles without a connection.</p></div><div class="panel"><h2>Your progress, kept local</h2><p>All four games and preferences stay in this browser on this device. App updates replace only application files; your progress stays separate. There are no ads, analytics, or AI uploads. Hosting may keep ordinary access logs. Clearing website data can erase progress.</p><p>To move phones: export a backup and save it to Files or send it via AirDrop. On the new phone, open this same app → Settings → Restore backup. All four games, unfinished puzzles, notes, and history are included.</p><div class="actions"><button id="backup" class="primary">Export backup ↓</button><button id="restore" class="secondary">Restore backup ↑</button></div><input id="backup-file" class="sr-only" type="file" accept="application/json,.json"><p class="note">Restore replaces current progress after confirmation.</p></div><div class="panel"><h2>Updates & storage</h2><p>The app checks for updates when it opens or returns to the foreground. New versions install automatically after progress is saved.</p><button id="check-update" class="secondary">Check for update</button><p class="update-note" id="update-status">Version ${APP_VERSION} · Progress stays on this device.</p><h2>A fresh start</h2><p>Daily puzzles reset at midnight Eastern. Completed results stay in your history. Want to clear everything?</p><button id="reset" class="secondary danger">Reset all progress</button><p class="note">Wordgarden ${APP_VERSION} · Independent word game.<br>Dictionary: <a href="./credits.html">sources & credits</a>.</p></div></div></section>`;
$('#splash-preview').onclick=()=>previewSplash($('#splash-preview-theme').value);
$('#check-update').onclick=()=>checkForUpdate(true);
for(const k of ['contrast','motion'])$('#'+k).onchange=e=>{state.settings[k]=e.target.checked;applySettings();save();};
$('#backup').onclick=()=>{let raw;try{raw=localStorage.getItem(KEY);}catch{}download(recoveryRaw!==null?recoveryRaw:JSON.stringify(state,null,2),'wordgarden-backup-'+today+'.json');};
$('#restore').onclick=()=>$('#backup-file').click();$('#backup-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5000000)throw Error('Backup is too large. Maximum 5 MB.');const restored=validateState(JSON.parse(await file.text()),answers,allowed);confirmAction('Restore this backup?','This replaces the games and settings currently on this device. Export your current progress first if you want to keep it.',()=>{recoveryRaw=null;state=restored;draft='';save();render();toast('Backup restored.');});}catch(err){toast(err.message||'Could not read backup.');}e.target.value='';};
$('#reset').onclick=()=>confirmAction('Reset all progress?','This permanently removes all four games, unfinished puzzles, history, and preferences from this browser. Export a backup first if you want to keep them.',()=>{recoveryRaw=null;state=newState();save();render();toast('Progress reset.');});}
function help(){if(view==='sudoku'||view==='ladder'){showDialog(view==='sudoku'?'Sudoku help':'Word Ladder help',view==='sudoku'?'<p>Fill every row, column, and 3×3 box with 1–9. Hint fills the selected incorrect or empty cell, or chooses one for you. Show answer reveals the complete grid and ends the puzzle without a win.</p>':'<p>Change one letter per step to connect the start and target. Hint suggests your next step. Show answer reveals a complete route from the start and ends the puzzle without a win.</p>');return;}if(view==='semantic'){showDialog('How to play Semantic Guessing','<p>Guess the secret word by meaning, not spelling. Every accepted word gets a rank in our word pack: #1 is the answer, and lower numbers mean closer associations.</p><p>There is no guess limit. Try broad topics, then follow your warmest guesses. A hint adds a closer word to your guesses and counts toward your total. AI similarities can be unexpected. Show answer reveals the secret word and ends the puzzle without a win.</p><p>Your puzzle and typing are saved automatically. Settings → Export backup includes this game for transferring to a new phone.</p>');return;}showDialog('A little wordplay.',`<p>Find the hidden <strong>five-letter word</strong> in six guesses. Enter any valid word, then use the tile clues to guide your next guess.</p>${legend()}<p><strong>Repeated letters:</strong> a letter is only marked as many times as it appears in the answer. Correct positions are counted first.</p><p>Today is the same puzzle for everyone and refreshes at midnight Eastern. Practice gives you unlimited fresh puzzles.</p><p>Hint reveals a letter without using a guess. Show answer ends the puzzle without a win.</p><button class="primary" id="got-it">Let’s play →</button>`);$('#got-it').onclick=()=>$('#dialog').close();}
function checkDay(){const now=dayKey();if(now===today)return false;today=now;draft='';render();toast('A fresh daily puzzle is ready.');return true;}
function connection(){$('#connection').textContent=!storageOK?'Progress not saved · export a backup':offlineReady?(navigator.onLine?'● Ready offline · Saved on this device':'● Offline · Saved on this device'):(navigator.onLine?'● Online · Preparing offline play':'Offline · Cache not confirmed');}
function setMenu(open,returnFocus=false){const wasOpen=!$('#app-menu').hidden;$('#app-menu').hidden=!open;$('#menu-toggle').setAttribute('aria-expanded',String(open));$('#menu-toggle').setAttribute('aria-label',open?'Close navigation':'Open navigation');if(open)$('#app-menu .selected')?.focus();else if(wasOpen&&returnFocus)$('#menu-toggle').focus();}
$('#menu-toggle').onclick=()=>setMenu($('#app-menu').hidden);
document.addEventListener('click',e=>{if(!$('#app-menu').hidden&&!e.target.closest('#app-menu,#menu-toggle'))setMenu(false);});
document.addEventListener('focusin',e=>{if(!$('#app-menu').hidden&&!e.target.closest('#app-menu,#menu-toggle'))setMenu(false);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#app-menu').hidden){e.preventDefault();setMenu(false,true);}});
$('#help').onclick=()=>{setMenu(false);help();};$('#close-dialog').onclick=()=>$('#dialog').close();$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>switchView(b.dataset.view));window.addEventListener('hashchange',()=>switchView(location.hash.slice(1)));document.addEventListener('keydown',e=>{if(!$('#app-menu').hidden||e.ctrlKey||e.metaKey||e.altKey||e.target.closest('input,select,textarea,dialog')||$('#dialog').open||$('#splash-screen')?.open)return;if(view==='sudoku'){puzzles.key(e);return;}if(['today','practice'].includes(view)&&(/^[a-z]$/i.test(e.key)||['Enter','Backspace'].includes(e.key))){if(e.key==='Enter'&&e.target.tagName==='BUTTON'&&!e.target.dataset.key)return;e.preventDefault();input(e.key);}});
window.addEventListener('storage',e=>{if(e.key!==KEY||!e.newValue)return;try{state=validateState(JSON.parse(e.newValue),answers,allowed);draft='';render();}catch{toast('Could not load progress from another tab.');}});
window.addEventListener('online',connection);window.addEventListener('offline',connection);document.addEventListener('visibilitychange',()=>{if(!document.hidden){checkDay();checkForUpdate();}});setInterval(checkDay,60000);switchView(location.hash.slice(1)||'today');connection();
let swRegistration=null,updateBusy=false,reloading=false;
const wasControlled='serviceWorker' in navigator&&!!navigator.serviceWorker.controller;
async function checkForUpdate(manual=false){if(!navigator.onLine){if(manual)toast('You are offline. Updates will check when you reconnect.');return;}if(!swRegistration||updateBusy){if(manual)toast('Offline setup is still getting ready.');return;}updateBusy=true;try{await swRegistration.update();if(swRegistration.waiting){swRegistration.waiting.postMessage({type:'ACTIVATE_UPDATE'});}if(manual)toast(swRegistration.installing||swRegistration.waiting?'Downloading the latest update…':'Update check complete.');}catch{if(manual)toast('Could not check for updates. Your saved puzzles are safe.');}finally{updateBusy=false;}}
if('serviceWorker'in navigator){navigator.serviceWorker.addEventListener('controllerchange',()=>{if(wasControlled&&!reloading){if(!storageOK){toast('Update ready. Export your progress before reopening.');return;}reloading=true;location.reload();}});navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).then(async reg=>{swRegistration=reg;const watch=worker=>worker?.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller)toast('Updating the app. Your progress is saved.');});reg.addEventListener('updatefound',()=>watch(reg.installing));watch(reg.installing);if(reg.waiting)reg.waiting.postMessage({type:'ACTIVATE_UPDATE'});await navigator.serviceWorker.ready;offlineReady=true;connection();checkForUpdate();}).catch(()=>{$('#connection').textContent='Online only · Offline setup unavailable';});}else{$('#connection').textContent='Offline play unavailable in this browser';}
window.addEventListener('online',()=>checkForUpdate());window.addEventListener('pageshow',()=>checkForUpdate());
if(navigator.storage?.persist)navigator.storage.persist().catch(()=>{});
